package com.runelite.poisondynamite;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ParamID;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Resolves the player's actual combat style from the selected attack style
 * (via the weapon styles cache enum, same lookup as script4525) instead of
 * guessing from equipment bonuses alone, and folds in prayer and stance
 * accuracy bonuses.
 */
@Singleton
class CombatStyleResolver
{
	enum Stance
	{
		ACCURATE, AGGRESSIVE, CONTROLLED, DEFENSIVE,
		RANGING, LONGRANGE, CASTING, DEFENSIVE_CASTING, OTHER
	}

	private final Client client;
	private final ItemManager itemManager;

	@Inject
	CombatStyleResolver(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Combat style category: stab, slash, crush, ranged or magic. */
	String getAttackStyle()
	{
		switch (getStance())
		{
			case RANGING:
			case LONGRANGE:
				return "ranged";
			case CASTING:
			case DEFENSIVE_CASTING:
				return "magic";
			default:
				return getMeleeType();
		}
	}

	int getEffectiveAttackLevel(String style)
	{
		Skill skill;
		switch (style)
		{
			case "ranged":
				skill = Skill.RANGED;
				break;
			case "magic":
				skill = Skill.MAGIC;
				break;
			default:
				skill = Skill.ATTACK;
				break;
		}
		int visibleLevel = client.getBoostedSkillLevel(skill);
		return HitChanceCalculator.getEffectiveLevel(
			visibleLevel, getPrayerMultiplier(style), getStanceBonus());
	}

	int getEquipmentAttackBonus(String style)
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return 0;
		}

		int total = 0;
		for (Item item : equipment.getItems())
		{
			ItemEquipmentStats eq = getEquipmentStats(item);
			if (eq == null)
			{
				continue;
			}
			switch (style)
			{
				case "stab":
					total += eq.getAstab();
					break;
				case "slash":
					total += eq.getAslash();
					break;
				case "crush":
					total += eq.getAcrush();
					break;
				case "magic":
					total += eq.getAmagic();
					break;
				case "ranged":
					total += eq.getArange();
					break;
			}
		}
		return total;
	}

	private Stance getStance()
	{
		int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
		int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);

		// from script4525: staffs use style 4 plus a casting mode varbit
		// for defensive casting
		if (styleIndex == 4)
		{
			styleIndex += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}

		Stance[] stances = getWeaponTypeStances(weaponType);
		if (styleIndex < 0 || styleIndex >= stances.length || stances[styleIndex] == null)
		{
			return Stance.OTHER;
		}
		return stances[styleIndex];
	}

	private Stance[] getWeaponTypeStances(int weaponType)
	{
		int weaponStyleEnum = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponType);
		if (weaponStyleEnum == -1)
		{
			return new Stance[0];
		}

		int[] structs = client.getEnum(weaponStyleEnum).getIntVals();
		Stance[] stances = new Stance[structs.length];
		int i = 0;
		for (int structId : structs)
		{
			StructComposition struct = client.getStructComposition(structId);
			String name = struct.getStringValue(ParamID.ATTACK_STYLE_NAME);
			Stance stance;
			try
			{
				stance = Stance.valueOf(name.toUpperCase());
			}
			catch (IllegalArgumentException e)
			{
				stance = Stance.OTHER;
			}
			// "Defensive" in slot 5 is defensive casting
			if (i == 5 && stance == Stance.DEFENSIVE)
			{
				stance = Stance.DEFENSIVE_CASTING;
			}
			stances[i++] = stance;
		}
		return stances;
	}

	private int getStanceBonus()
	{
		int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
		switch (getStance())
		{
			case ACCURATE:
				return 3;
			case CONTROLLED:
				return 1;
			case RANGING:
			case CASTING:
				// index 0 is the accurate stance for ranged and powered staves
				return styleIndex == 0 ? 3 : 0;
			default:
				return 0;
		}
	}

	private double getPrayerMultiplier(String style)
	{
		switch (style)
		{
			case "ranged":
				if (client.isPrayerActive(Prayer.RIGOUR))
				{
					return 1.20;
				}
				if (client.isPrayerActive(Prayer.DEADEYE))
				{
					return 1.18;
				}
				if (client.isPrayerActive(Prayer.EAGLE_EYE))
				{
					return 1.15;
				}
				if (client.isPrayerActive(Prayer.HAWK_EYE))
				{
					return 1.10;
				}
				if (client.isPrayerActive(Prayer.SHARP_EYE))
				{
					return 1.05;
				}
				return 1.0;
			case "magic":
				if (client.isPrayerActive(Prayer.AUGURY))
				{
					return 1.25;
				}
				if (client.isPrayerActive(Prayer.MYSTIC_VIGOUR))
				{
					return 1.18;
				}
				if (client.isPrayerActive(Prayer.MYSTIC_MIGHT))
				{
					return 1.15;
				}
				if (client.isPrayerActive(Prayer.MYSTIC_LORE))
				{
					return 1.10;
				}
				if (client.isPrayerActive(Prayer.MYSTIC_WILL))
				{
					return 1.05;
				}
				return 1.0;
			default:
				if (client.isPrayerActive(Prayer.PIETY))
				{
					return 1.20;
				}
				if (client.isPrayerActive(Prayer.CHIVALRY)
					|| client.isPrayerActive(Prayer.INCREDIBLE_REFLEXES))
				{
					return 1.15;
				}
				if (client.isPrayerActive(Prayer.IMPROVED_REFLEXES))
				{
					return 1.10;
				}
				if (client.isPrayerActive(Prayer.CLARITY_OF_THOUGHT))
				{
					return 1.05;
				}
				return 1.0;
		}
	}

	private String getMeleeType()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return "crush";
		}

		Item[] items = equipment.getItems();
		int weaponIdx = EquipmentInventorySlot.WEAPON.getSlotIdx();
		if (weaponIdx >= items.length)
		{
			return "crush";
		}

		ItemEquipmentStats eq = getEquipmentStats(items[weaponIdx]);
		if (eq == null)
		{
			// unarmed punches are crush
			return "crush";
		}

		int stab = eq.getAstab();
		int slash = eq.getAslash();
		int crush = eq.getAcrush();
		if (slash >= stab && slash >= crush)
		{
			return "slash";
		}
		if (stab >= crush)
		{
			return "stab";
		}
		return "crush";
	}

	private ItemEquipmentStats getEquipmentStats(Item item)
	{
		if (item == null || item.getId() == -1)
		{
			return null;
		}
		ItemStats stats = itemManager.getItemStats(item.getId());
		if (stats == null || !stats.isEquipable())
		{
			return null;
		}
		return stats.getEquipment();
	}
}

package com.runelite.poisondynamite;

final class HitChanceCalculator
{
	private HitChanceCalculator()
	{
	}

	static double calculate(int effectiveAttackLevel, int equipmentAttackBonus,
		int npcDefenceLevel, int npcStyleDefenceBonus)
	{
		int attackRoll = effectiveAttackLevel * (equipmentAttackBonus + 64);
		int defenceRoll = (npcDefenceLevel + 9) * (npcStyleDefenceBonus + 64);

		if (attackRoll > defenceRoll)
		{
			return 1.0 - (defenceRoll + 2.0) / (2.0 * attackRoll + 1.0);
		}
		else
		{
			return (double) attackRoll / (2.0 * defenceRoll + 1.0);
		}
	}

	static int getEffectiveLevel(int visibleLevel, double prayerMult, int stanceBonus)
	{
		return (int) Math.floor(visibleLevel * prayerMult) + stanceBonus + 8;
	}
}

package com.runelite.poisondynamite;

/**
 * Recovers an NPC's hitpoints from the health bar ratio the server sends.
 *
 * The server computes {@code ratio = 1 + (scale - 1) * health / maxHealth} for a
 * living NPC, so inverting it gives a range of possible hitpoints; we take the
 * midpoint. The result is exact when maxHealth fits inside the scale.
 */
final class NpcHealth
{
	private NpcHealth()
	{
	}

	/**
	 * @return estimated current hitpoints, 0 if dead, or -1 when unknown
	 */
	static int estimate(int healthRatio, int healthScale, int maxHealth)
	{
		if (healthRatio < 0 || healthScale <= 0 || maxHealth <= 0)
		{
			return -1;
		}

		if (healthRatio == 0)
		{
			return 0;
		}

		int minHealth = 1;
		int maxPossible;
		if (healthScale > 1)
		{
			if (healthRatio > 1)
			{
				// health = 0 forces ratio = 0 on the server, so ratio = 1 carries no lower bound
				minHealth = (maxHealth * (healthRatio - 1) + healthScale - 2) / (healthScale - 1);
			}
			maxPossible = Math.min(maxHealth, (maxHealth * healthRatio - 1) / (healthScale - 1));
		}
		else
		{
			maxPossible = maxHealth;
		}

		return (minHealth + maxPossible + 1) / 2;
	}
}

package com.runelite.poisondynamite;

import java.time.Duration;
import java.time.Instant;

/**
 * Models the poison ticking on a single NPC.
 *
 * NPCs have no poison varp to read, so the poison value is inferred from the
 * hitsplats we see: poison deals {@code ceil(value / 5)} damage every
 * {@link #POISON_TICK_MILLIS} and drops the value by one, and every source sets
 * the value to a multiple of five. So a splat of {@code d} damage means the value
 * was {@code 5d} for that hit whenever the damage differs from the previous
 * splat — the first splat we see, a step down as the poison decays, or a step up
 * when a stronger poison is applied. Equal damage just decrements. Any wrong
 * initial guess therefore corrects itself on the next step down.
 */
class NpcPoison
{
	static final int POISON_TICK_MILLIS = 18200;

	private int remainingHits;
	private int lastDamage;
	private Instant lastHit;
	private int healthEstimate = -1;

	void onPoisonHit(int damage, Instant now)
	{
		if (damage <= 0)
		{
			return;
		}

		if (!isActive() || damage != lastDamage)
		{
			remainingHits = damage * 5 - 1;
		}
		else
		{
			remainingHits--;
		}

		lastDamage = damage;
		lastHit = now;

		// keep the estimate fresh while the health bar is hidden
		if (healthEstimate > 0)
		{
			healthEstimate = Math.max(0, healthEstimate - damage);
		}
	}

	boolean isActive()
	{
		return remainingHits > 0;
	}

	int getNextDamage()
	{
		return damageAt(remainingHits);
	}

	int getRemainingHits()
	{
		return Math.max(0, remainingHits);
	}

	int getRemainingDamage()
	{
		return damageOverHits(getRemainingHits());
	}

	long getMillisUntilNextHit(Instant now)
	{
		if (!isActive() || lastHit == null)
		{
			return 0;
		}
		long elapsed = Duration.between(lastHit, now).toMillis();
		return Math.max(0, POISON_TICK_MILLIS - elapsed);
	}

	long getMillisUntilEnd(Instant now)
	{
		if (!isActive())
		{
			return 0;
		}
		return getMillisUntilNextHit(now) + (long) (remainingHits - 1) * POISON_TICK_MILLIS;
	}

	/**
	 * @return hits needed to finish an NPC on {@code hitpoints}, or -1 if the
	 * poison wears off first
	 */
	int getHitsUntilDeath(int hitpoints)
	{
		if (hitpoints <= 0)
		{
			return 0;
		}

		int dealt = 0;
		for (int hit = 1; hit <= remainingHits; hit++)
		{
			dealt += damageAt(remainingHits - hit + 1);
			if (dealt >= hitpoints)
			{
				return hit;
			}
		}
		return -1;
	}

	/**
	 * @return time until the poison finishes the NPC, or -1 if it never does
	 */
	long getMillisUntilDeath(int hitpoints, Instant now)
	{
		int hits = getHitsUntilDeath(hitpoints);
		if (hits < 0)
		{
			return -1;
		}
		if (hits == 0)
		{
			return 0;
		}
		return getMillisUntilNextHit(now) + (long) (hits - 1) * POISON_TICK_MILLIS;
	}

	void updateHealth(int healthRatio, int healthScale, int maxHealth)
	{
		int estimate = NpcHealth.estimate(healthRatio, healthScale, maxHealth);
		if (estimate >= 0)
		{
			healthEstimate = estimate;
		}
	}

	int getHealthEstimate()
	{
		return healthEstimate;
	}

	private static int damageAt(int poisonValue)
	{
		return poisonValue <= 0 ? 0 : (poisonValue + 4) / 5;
	}

	/**
	 * Total damage of a poison with {@code hits} hits left: five hits at each
	 * damage step as the value counts down to zero.
	 */
	private static int damageOverHits(int hits)
	{
		int steps = hits / 5;
		int remainder = hits % 5;
		return 5 * (steps * (steps + 1) / 2) + remainder * (steps + 1);
	}
}

package com.runelite.poisondynamite;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
class NpcStatsManager
{
	private static final HttpUrl WIKI_API_URL = HttpUrl.parse(
		"https://oldschool.runescape.wiki/api.php");
	private static final String USER_AGENT =
		"poison-dynamite-runelite-plugin (github.com/yonnski/poison-dynamite)";
	private static final long RETRY_BACKOFF_MILLIS = 30_000;

	private final OkHttpClient httpClient;
	private final Map<String, NpcDefenceStats> cache = new ConcurrentHashMap<>();
	// Track in-flight requests so we don't duplicate fetches
	private final Map<String, Boolean> pending = new ConcurrentHashMap<>();
	// Failed lookups are retried after a backoff instead of being cached as zeros
	private final Map<String, Instant> failures = new ConcurrentHashMap<>();

	@Inject
	NpcStatsManager(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	NpcDefenceStats getStats(String npcName, int npcId)
	{
		if (npcName == null)
		{
			return null;
		}

		String key = key(npcName, npcId);
		NpcDefenceStats cached = cache.get(key);
		if (cached != null)
		{
			return cached;
		}

		Instant failedAt = failures.get(key);
		if (failedAt != null
			&& Instant.now().isBefore(failedAt.plusMillis(RETRY_BACKOFF_MILLIS)))
		{
			return null;
		}

		// Start fetch if not already pending
		if (pending.putIfAbsent(key, Boolean.TRUE) == null)
		{
			fetchStats(npcName, npcId, key, false);
		}

		return null;
	}

	boolean isUnavailable(String npcName, int npcId)
	{
		return npcName != null && failures.containsKey(key(npcName, npcId));
	}

	private static String key(String npcName, int npcId)
	{
		return npcName + ":" + npcId;
	}

	private void fetchStats(String npcName, int npcId, String cacheKey, boolean byId)
	{
		String filter = byId
			? ".where('id'," + npcId + ")"
			: ".where('name','" + npcName.replace("'", "\\'") + "')";
		String query = "bucket('infobox_monster')" +
			".select('id','defence_level','stab_defence_bonus','slash_defence_bonus'," +
			"'crush_defence_bonus','magic_defence_bonus','range_defence_bonus')" +
			filter + ".run()";

		HttpUrl url = WIKI_API_URL.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to fetch NPC stats for {}", npcName, e);
				fail(cacheKey);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						log.warn("Wiki API returned {} for {}", response.code(), npcName);
						fail(cacheKey);
						return;
					}

					String body = response.body().string();
					NpcDefenceStats stats = parseResponse(body, npcId);
					if (stats == null)
					{
						if (!byId)
						{
							// in-game name may not match the wiki page name;
							// retry the lookup by NPC id
							log.debug("No wiki match by name for {}, retrying by id {}", npcName, npcId);
							fetchStats(npcName, npcId, cacheKey, true);
							return;
						}
						log.warn("No wiki stats found for {} (id={})", npcName, npcId);
						fail(cacheKey);
						return;
					}

					// defence stats are in hand; poison resistance comes from the
					// page wikitext (the bucket's poison_resistance field is broken)
					fetchPoisonResistance(npcName, npcId, cacheKey, stats);
				}
				catch (Exception e)
				{
					log.warn("Error parsing NPC stats for {}", npcName, e);
					fail(cacheKey);
				}
			}
		});
	}

	private void fetchPoisonResistance(String npcName, int npcId, String cacheKey,
		NpcDefenceStats stats)
	{
		HttpUrl url = WIKI_API_URL.newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", npcName)
			.addQueryParameter("prop", "wikitext")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to fetch poison resistance for {}", npcName, e);
				succeed(cacheKey, stats);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				String resistance = null;
				try (response)
				{
					if (response.isSuccessful())
					{
						resistance = parsePoisonResistance(response.body().string(), npcId);
					}
				}
				catch (Exception e)
				{
					log.warn("Error parsing poison resistance for {}", npcName, e);
				}
				succeed(cacheKey, stats.withPoisonResistance(resistance));
				log.debug("Poison resistance for {} (id={}): {}", npcName, npcId, resistance);
			}
		});
	}

	private void succeed(String cacheKey, NpcDefenceStats stats)
	{
		cache.put(cacheKey, stats);
		failures.remove(cacheKey);
		pending.remove(cacheKey);
	}

	private void fail(String cacheKey)
	{
		failures.put(cacheKey, Instant.now());
		pending.remove(cacheKey);
	}

	// Reads |poisonresistance (or |poisonresistanceN for versioned infoboxes)
	// from the page wikitext, matching the version whose |idN list contains
	// the target NPC id, falling back to the first value on the page.
	static String parsePoisonResistance(String parseApiJson, int targetNpcId)
	{
		JsonObject root = new JsonParser().parse(parseApiJson).getAsJsonObject();
		if (!root.has("parse"))
		{
			return null;
		}
		JsonObject parse = root.getAsJsonObject("parse");
		if (!parse.has("wikitext"))
		{
			return null;
		}
		String wikitext = parse.getAsJsonObject("wikitext").get("*").getAsString();

		Map<String, String> resistanceBySuffix = new java.util.HashMap<>();
		String matchedSuffix = null;
		String firstSuffix = null;

		java.util.regex.Matcher m = INFOBOX_PARAM_PATTERN.matcher(wikitext);
		while (m.find())
		{
			String param = m.group(1);
			String suffix = m.group(2);
			String value = m.group(3).trim();

			if (param.equals("poisonresistance"))
			{
				resistanceBySuffix.putIfAbsent(suffix, value);
				if (firstSuffix == null)
				{
					firstSuffix = suffix;
				}
			}
			else if (matchedSuffix == null) // id param
			{
				for (String idStr : value.split(","))
				{
					try
					{
						if (Integer.parseInt(idStr.trim()) == targetNpcId)
						{
							matchedSuffix = suffix;
							break;
						}
					}
					catch (NumberFormatException ignored)
					{
					}
				}
			}
		}

		String value = matchedSuffix != null ? resistanceBySuffix.get(matchedSuffix) : null;
		if (value == null && firstSuffix != null)
		{
			value = resistanceBySuffix.get(firstSuffix);
		}
		if (value == null || value.isEmpty())
		{
			return null;
		}
		return value.toLowerCase();
	}

	private static final java.util.regex.Pattern INFOBOX_PARAM_PATTERN =
		java.util.regex.Pattern.compile("\\|\\s*(id|poisonresistance)(\\d*)\\s*=\\s*([^\\n|]*)");

	// The bucket API returns one row per infobox version: scalar stat fields
	// plus an "id" array listing the NPC ids that version covers.
	static NpcDefenceStats parseResponse(String json, int targetNpcId)
	{
		JsonObject root = new JsonParser().parse(json).getAsJsonObject();
		if (!root.has("bucket") || !root.get("bucket").isJsonArray())
		{
			return null;
		}

		JsonArray rows = root.getAsJsonArray("bucket");
		if (rows.size() == 0)
		{
			return null;
		}

		JsonObject match = null;
		for (JsonElement rowElem : rows)
		{
			if (rowElem.isJsonObject() && rowContainsId(rowElem.getAsJsonObject(), targetNpcId))
			{
				match = rowElem.getAsJsonObject();
				break;
			}
		}
		if (match == null)
		{
			match = rows.get(0).getAsJsonObject();
		}

		return new NpcDefenceStats(
			getInt(match, "defence_level"),
			getInt(match, "stab_defence_bonus"),
			getInt(match, "slash_defence_bonus"),
			getInt(match, "crush_defence_bonus"),
			getInt(match, "magic_defence_bonus"),
			getInt(match, "range_defence_bonus")
		);
	}

	private static boolean rowContainsId(JsonObject row, int targetNpcId)
	{
		if (!row.has("id"))
		{
			return false;
		}
		JsonElement idElem = row.get("id");
		if (idElem.isJsonArray())
		{
			for (JsonElement e : idElem.getAsJsonArray())
			{
				if (asInt(e, -1) == targetNpcId)
				{
					return true;
				}
			}
			return false;
		}
		return asInt(idElem, -1) == targetNpcId;
	}

	private static int getInt(JsonObject row, String key)
	{
		if (!row.has(key))
		{
			return 0;
		}
		JsonElement elem = row.get(key);
		if (elem.isJsonArray())
		{
			JsonArray array = elem.getAsJsonArray();
			elem = array.size() > 0 ? array.get(0) : null;
		}
		return elem == null ? 0 : asInt(elem, 0);
	}

	private static int asInt(JsonElement elem, int fallback)
	{
		if (elem == null || elem.isJsonNull() || !elem.isJsonPrimitive())
		{
			return fallback;
		}
		try
		{
			return elem.getAsInt();
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	static class NpcDefenceStats
	{
		final int defenceLevel;
		final int stabDef;
		final int slashDef;
		final int crushDef;
		final int magicDef;
		final int rangeDef;
		// "0", "100", "200" or "poison" (immune); null when unknown
		final String poisonResistance;

		NpcDefenceStats(int defenceLevel, int stabDef, int slashDef, int crushDef,
			int magicDef, int rangeDef)
		{
			this(defenceLevel, stabDef, slashDef, crushDef, magicDef, rangeDef, null);
		}

		NpcDefenceStats(int defenceLevel, int stabDef, int slashDef, int crushDef,
			int magicDef, int rangeDef, String poisonResistance)
		{
			this.defenceLevel = defenceLevel;
			this.stabDef = stabDef;
			this.slashDef = slashDef;
			this.crushDef = crushDef;
			this.magicDef = magicDef;
			this.rangeDef = rangeDef;
			this.poisonResistance = poisonResistance;
		}

		NpcDefenceStats withPoisonResistance(String resistance)
		{
			return new NpcDefenceStats(defenceLevel, stabDef, slashDef, crushDef,
				magicDef, rangeDef, resistance);
		}

		// resistance 100 blocks poison, 200 blocks poison and venom, and
		// "poison" marks poison-based monsters — only 0 can be poisoned
		boolean isPoisonImmune()
		{
			return poisonResistance != null && !"0".equals(poisonResistance);
		}

		int getDefenceForStyle(String style)
		{
			if (style == null)
			{
				return stabDef;
			}
			switch (style.toLowerCase())
			{
				case "slash":
					return slashDef;
				case "crush":
					return crushDef;
				case "magic":
					return magicDef;
				case "ranged":
				case "range":
					return rangeDef;
				case "stab":
				default:
					return stabDef;
			}
		}

		@Override
		public String toString()
		{
			return "NpcDefenceStats{def=" + defenceLevel +
				", stab=" + stabDef + ", slash=" + slashDef +
				", crush=" + crushDef + ", magic=" + magicDef +
				", range=" + rangeDef + "}";
		}
	}
}

package com.runelite.poisondynamite;

import java.time.Instant;
import net.runelite.api.NPC;

/**
 * Per-NPC state for one Dynamite(p) application: waiting for the detonation
 * hitsplat, counting down the poison cycle, then briefly showing the result.
 */
class PoisonAttempt
{
	static final int POISON_CYCLE_TICKS = 30;

	final NPC npc;
	boolean awaitingDetonationHit = true;
	int ticksAwaitingDetonation;
	int remainingTicks = -1;
	Instant resultTime;
	boolean poisonSuccess;
	boolean poisonFailed;
	boolean detonationMiss;

	PoisonAttempt(NPC npc)
	{
		this.npc = npc;
	}

	/**
	 * A second dynamite click on the same NPC. Mid-countdown it is usually just a
	 * check click, so the running poison timer is kept. While the previous throw is
	 * still in flight — or was cancelled — this click is the one that matters, so
	 * the detonation window restarts rather than expiring on the old click's clock
	 * and dropping the incoming splat.
	 *
	 * @return true if the existing attempt absorbed this click
	 */
	boolean absorbReclick()
	{
		if (isResolved())
		{
			return false;
		}
		if (awaitingDetonationHit)
		{
			ticksAwaitingDetonation = 0;
		}
		return true;
	}

	boolean isCountingDown()
	{
		return remainingTicks >= 0;
	}

	boolean isResolved()
	{
		return poisonSuccess || poisonFailed;
	}

	void startCountdown()
	{
		awaitingDetonationHit = false;
		remainingTicks = POISON_CYCLE_TICKS;
	}

	void resolve(boolean success)
	{
		poisonSuccess = success;
		poisonFailed = !success;
		awaitingDetonationHit = false;
		resultTime = Instant.now();
	}

	double getProgress()
	{
		if (!isCountingDown())
		{
			return 0.0;
		}
		return 1.0 - (double) remainingTicks / POISON_CYCLE_TICKS;
	}

	int getRemainingSeconds()
	{
		int ticks = isCountingDown() ? remainingTicks : POISON_CYCLE_TICKS;
		return (int) Math.ceil(ticks * PoisonDynamitePlugin.GAME_TICK_MILLIS / 1000.0);
	}
}

