	private NPCManager npcManager;

	private final Map<NPC, PoisonAttempt> attempts = new HashMap<>();

	// poison ticking on NPCs we have poisoned, kept until it wears off or they die
	private final Map<NPC, NpcPoison> poisons = new HashMap<>();

	// cumulative defence drained by special attacks, per NPC instance
	private final Map<NPC, Integer> defenceDrains = new HashMap<>();

	private NPC trackedNpc;

	@Getter
	private String trackedNpcName;

	@Getter
	private int trackedNpcId = -1;

	@Getter
	private int sessionAttempts;

	@Getter
	private int sessionProcs;

	@Provides
	PoisonDynamiteConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PoisonDynamiteConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(npcOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(npcOverlay);
		reset();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_NPC)
		{
			return;
		}

		var selectedWidget = client.getSelectedWidget();
		if (selectedWidget == null || selectedWidget.getItemId() != ItemID.LOVAKENGJ_DYNAMITE_POISON)
		{
			return;
		}

		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null)
		{
			return;
		}

		trackNpc(npc);

		PoisonAttempt existing = attempts.get(npc);
		if (existing != null && existing.absorbReclick())
		{
			return;
		}

		attempts.put(npc, new PoisonAttempt(npc));
		sessionAttempts++;
		log.debug("Dynamite(p) used on NPC: {} (id={}), awaiting detonation hit", npc.getName(), npc.getId());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		int amount = hitsplat.getAmount();
		PoisonAttempt attempt = attempts.get(actor);

		if (hitsplat.getHitsplatType() == HitsplatID.POISON)
		{
			trackPoisonHit(actor, attempt, amount);
		}

		if (attempt == null || attempt.isResolved())
		{
			return;
		}

		if (hitsplat.getHitsplatType() == HitsplatID.POISON)
		{
			log.debug("Poison proc on {}! Damage: {}", attempt.npc.getName(), amount);
			attempt.resolve(true);
			sessionProcs++;
				if (config.notifyOnProc())
			{
				notifier.notify("Poison proc on " + attempt.npc.getName());
			}
			return;
		}

		// only our own hitsplat can be the detonation result
		if (attempt.awaitingDetonationHit && hitsplat.isMine())
		{
			if (amount <= 0)
			{
				log.debug("Dynamite missed on {} (hit 0)", attempt.npc.getName());
				attempt.detonationMiss = true;
				attempt.resolve(false);
			}
			else if (isPoisonImmune(attempt.npc))
			{
				log.debug("Dynamite hit on {} for {}, but it is immune to poison",
					attempt.npc.getName(), amount);
				attempt.resolve(false);
			}
			else
			{
				attempt.startCountdown();
				log.debug("Dynamite hit on {} for {}, countdown started", attempt.npc.getName(), amount);
			}
		}
	}

	/**
	 * Feed a poison hitsplat into the model for an NPC we poisoned. The first
	 * splat of an attempt starts the track; later splats keep it anchored.
	 */
	private void trackPoisonHit(Actor actor, PoisonAttempt attempt, int amount)
	{
		if (!(actor instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) actor;
		NpcPoison poison = poisons.get(npc);
		if (poison == null)
		{
			if (attempt == null || attempt.isResolved())
			{
				// not a poison we applied
				return;
			}
			poison = new NpcPoison();
			poisons.put(npc, poison);
		}

		poison.onPoisonHit(amount, Instant.now());
		log.debug("Poison on {}: {} damage, {} hits left ({} damage)", npc.getName(), amount,
			poison.getRemainingHits(), poison.getRemainingDamage());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updatePoisons();

		Iterator<PoisonAttempt> it = attempts.values().iterator();
		while (it.hasNext())
		{
			PoisonAttempt attempt = it.next();
			if (attempt.isResolved())
			{
				if (attempt.resultTime != null
					&& Duration.between(attempt.resultTime, Instant.now()).toMillis() >= RESULT_DISPLAY_MILLIS)
				{
					it.remove();
				}
			}
			else if (attempt.awaitingDetonationHit)
			{
				if (++attempt.ticksAwaitingDetonation > DETONATION_TIMEOUT_TICKS)
				{
					log.debug("No detonation hitsplat on {}, abandoning attempt", attempt.npc.getName());
					it.remove();
				}
			}
			else if (isPoisonImmune(attempt.npc))
			{
				// wiki immunity data can land after the countdown has started
				log.debug("{} is immune to poison, abandoning countdown", attempt.npc.getName());
				attempt.resolve(false);
			}
			else if (--attempt.remainingTicks <= 0)
			{
				log.debug("Poison timer expired on {}", attempt.npc.getName());
				attempt.resolve(false);
			}
		}
	}

	/**
	 * Refresh the hitpoints estimate from the health bar while it is visible and
	 * drop poisons that have worn off.
	 */
	private void updatePoisons()
	{
		Iterator<Map.Entry<NPC, NpcPoison>> it = poisons.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<NPC, NpcPoison> entry = it.next();
			NpcPoison poison = entry.getValue();
			if (!poison.isActive())
			{
				log.debug("Poison wore off on {}", entry.getKey().getName());
				it.remove();
				continue;
			}

			NPC npc = entry.getKey();
			Integer maxHealth = npcManager.getHealth(npc.getId());
			if (maxHealth != null)
			{
				poison.updateHealth(npc.getHealthRatio(), npc.getHealthScale(), maxHealth);
			}
		}
	}

	private boolean isPoisonImmune(NPC npc)
	{
		NpcStatsManager.NpcDefenceStats stats = npcStatsManager.getStats(npc.getName(), npc.getId());
		return stats != null && stats.isPoisonImmune();
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		attempts.remove(event.getNpc());
		poisons.remove(event.getNpc());
		defenceDrains.remove(event.getNpc());
		if (event.getNpc() == trackedNpc)
		{
			trackedNpc = null;
		}
	}

	@Subscribe
	public void onSpecialCounterUpdate(SpecialCounterUpdate event)
	{
		if (event.getWorld() != client.getWorld())
		{
			return;
		}

		WorldView wv = client.getTopLevelWorldView();
		NPC npc = wv == null ? null : wv.npcs().byIndex(event.getNpcIndex());
		if (npc == null)
		{
			return;
		}

		NpcStatsManager.NpcDefenceStats stats = npcStatsManager.getStats(npc.getName(), npc.getId());
		if (stats == null)
		{
			return;
		}

		int current = Math.max(0, stats.defenceLevel - defenceDrains.getOrDefault(npc, 0));
		int drain = defenceDrain(event.getWeapon(), event.getHit(), current);
		if (drain > 0)
		{
			defenceDrains.merge(npc, drain, Integer::sum);
			log.debug("Defence drain on {}: -{} ({} -> {})", npc.getName(), drain, current, current - drain);
		}
	}

	private static int defenceDrain(SpecialWeapon weapon, int hit, int currentDefence)
	{
		if (hit <= 0)
		{
			return 0;
		}
		switch (weapon)
		{
			case DRAGON_WARHAMMER:
				return currentDefence * 30 / 100;
			case ELDER_MAUL:
				return currentDefence * 35 / 100;
			case BANDOS_GODSWORD:
			case BONE_DAGGER:
			case DORGESHUUN_CROSSBOW:
				return hit;
			case BARRELCHEST_ANCHOR:
				return hit / 10;
			case BULWARK:
			case TONALZTICS_OF_RALOS:
			case EMBERLIGHT:
				return currentDefence * 10 / 100;
			case ACCURSED_SCEPTRE:
				return currentDefence * 15 / 100;
			case ARCLIGHT:
			case DARKLIGHT:
				return currentDefence * 5 / 100;
			default:
				return 0;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		poisons.remove(event.getActor());

		PoisonAttempt attempt = attempts.get(event.getActor());
		if (attempt != null && !attempt.isResolved())
		{
			attempt.resolve(false);
		}
	}

	Iterable<PoisonAttempt> getAttempts()
	{
		return attempts.values();
	}

	NpcPoison getTrackedPoison()
	{
		return trackedNpc == null ? null : poisons.get(trackedNpc);
	}

	int getTrackedDefenceDrain()
	{
		return trackedNpc == null ? 0 : defenceDrains.getOrDefault(trackedNpc, 0);
	}

	int getDynamiteCount()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		return inventory == null ? 0 : inventory.count(ItemID.LOVAKENGJ_DYNAMITE_POISON);
	}

	NpcStatsManager getNpcStatsManager()
	{
		return npcStatsManager;
	}

	void reset()
	{
		attempts.clear();
		poisons.clear();
		defenceDrains.clear();
		trackedNpc = null;
		trackedNpcName = null;
		trackedNpcId = -1;
		sessionAttempts = 0;
		sessionProcs = 0;
	}

	private void trackNpc(NPC npc)
	{
		trackedNpc = npc;
		trackedNpcName = npc.getName() != null ? npc.getName() : "Unknown";
		trackedNpcId = npc.getId();
		npcStatsManager.getStats(trackedNpcName, trackedNpcId);
	}
}

package com.runelite.poisondynamite;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class HitChanceCalculatorTest
{
	private static final double EPSILON = 1e-9;

	@Test
	public void calculateWhenAttackRollExceedsDefenceRoll()
	{
		// attackRoll = 50 * 64 = 3200, defenceRoll = 10 * 64 = 640
		double expected = 1.0 - 642.0 / 6401.0;
		assertEquals(expected, HitChanceCalculator.calculate(50, 0, 1, 0), EPSILON);
	}

	@Test
	public void calculateWhenDefenceRollExceedsAttackRoll()
	{
		// attackRoll = 10 * 64 = 640, defenceRoll = 109 * 164 = 17876
		double expected = 640.0 / 35753.0;
		assertEquals(expected, HitChanceCalculator.calculate(10, 0, 100, 100), EPSILON);
	}

	@Test
	public void calculateEqualRollsIsNearHalf()
	{
		// attackRoll == defenceRoll = 640
		double chance = HitChanceCalculator.calculate(10, 0, 1, 0);
		assertEquals(640.0 / 1281.0, chance, EPSILON);
		assertTrue(chance < 0.5);
	}

	@Test
	public void effectiveLevelFloorsPrayerBoostBeforeBonuses()
	{
		// floor(99 * 1.2) = 118, + 3 stance + 8 base
		assertEquals(129, HitChanceCalculator.getEffectiveLevel(99, 1.2, 3));
		// no prayer, no stance
		assertEquals(107, HitChanceCalculator.getEffectiveLevel(99, 1.0, 0));
	}
}

package com.runelite.poisondynamite;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class NpcHealthTest
{
	@Test
	public void estimateIsExactWhenMaxHealthFitsInScale()
	{
		// server: ratio = 1 + (scale - 1) * health / maxHealth = 1 + 29 * 7 / 10 = 21
		assertEquals(7, NpcHealth.estimate(21, 30, 10));
	}

	@Test
	public void estimateInterpolatesWhenMaxHealthExceedsScale()
	{
		// ratio = 1 + 29 * 128 / 255 = 15
		assertEquals(128, NpcHealth.estimate(15, 30, 255));
	}

	@Test
	public void estimateIsMaxHealthAtFullRatio()
	{
		assertEquals(100, NpcHealth.estimate(30, 30, 100));
	}

	@Test
	public void estimateIsZeroWhenRatioIsZero()
	{
		assertEquals(0, NpcHealth.estimate(0, 30, 255));
	}

	@Test
	public void estimateIsMidpointWhenScaleCarriesNoInformation()
	{
		// scale of 1 means ratio is always 1 while alive, so only the upper bound is known
		assertEquals(51, NpcHealth.estimate(1, 1, 100));
	}

	@Test
	public void estimateIsUnknownWithoutAHealthBar()
	{
		assertEquals(-1, NpcHealth.estimate(-1, 30, 255));
		assertEquals(-1, NpcHealth.estimate(15, 0, 255));
		assertEquals(-1, NpcHealth.estimate(15, 30, 0));
	}
}

package com.runelite.poisondynamite;

import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class NpcPoisonTest
{
	private static final Instant T0 = Instant.ofEpochMilli(1_000_000);

	private static Instant plusMillis(long millis)
	{
		return T0.plusMillis(millis);
	}

	@Test
	public void newPoisonIsInactiveUntilTheFirstHit()
	{
		assertFalse(new NpcPoison().isActive());
	}

	@Test
	public void firstHitAnchorsPoisonValueFromItsDamage()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(6, T0);

		assertTrue(poison.isActive());
		// damage 6 means a poison value of 30, of which this hit consumed one
		assertEquals(29, poison.getRemainingHits());
		assertEquals(6, poison.getNextDamage());
		// the full 30-hit poison deals 105, minus the 6 already dealt
		assertEquals(99, poison.getRemainingDamage());
	}

	@Test
	public void repeatedHitsOfEqualDamageDecrementRemainingHits()
	{
		NpcPoison poison = new NpcPoison();
		for (int i = 0; i < 5; i++)
		{
			poison.onPoisonHit(6, T0);
		}

		assertEquals(25, poison.getRemainingHits());
		assertEquals(5, poison.getNextDamage());
	}

	@Test
	public void damageSteppingDownReAnchorsAMisjudgedPoisonValue()
	{
		// joining mid-poison: the first splat we see is already down to 5
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(5, T0);
		assertEquals(24, poison.getRemainingHits());

		// a step down to 4 means the value was exactly 20 for that hit
		poison.onPoisonHit(4, T0);
		assertEquals(19, poison.getRemainingHits());
	}

	@Test
	public void strongerPoisonReAnchorsUpward()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(4, T0);
		poison.onPoisonHit(6, T0);

		assertEquals(29, poison.getRemainingHits());
	}

	@Test
	public void poisonWearsOffAfterItsFinalHit()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(1, T0);
		assertEquals(4, poison.getRemainingHits());
		assertEquals(4, poison.getRemainingDamage());

		for (int i = 0; i < 4; i++)
		{
			poison.onPoisonHit(1, T0);
		}

		assertFalse(poison.isActive());
		assertEquals(0, poison.getRemainingHits());
		assertEquals(0, poison.getRemainingDamage());
	}

	@Test
	public void millisUntilNextHitCountsDownFromTheLastHit()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(6, T0);

		assertEquals(NpcPoison.POISON_TICK_MILLIS, poison.getMillisUntilNextHit(T0));
		assertEquals(13_200, poison.getMillisUntilNextHit(plusMillis(5000)));
		assertEquals(0, poison.getMillisUntilNextHit(plusMillis(20_000)));
	}

	@Test
	public void millisUntilEndSpansEveryRemainingHit()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(6, T0);

		assertEquals(29L * NpcPoison.POISON_TICK_MILLIS, poison.getMillisUntilEnd(T0));
	}

	@Test
	public void hitsUntilDeathAccumulatesTheDecayingDamage()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(6, T0);

		// 6 + 6 + 6 + 6 = 24 finishes a 20 hitpoint NPC on the fourth hit
		assertEquals(4, poison.getHitsUntilDeath(20));
		assertEquals(4L * NpcPoison.POISON_TICK_MILLIS, poison.getMillisUntilDeath(20, T0));
	}

	@Test
	public void hitsUntilDeathIsUnknownWhenPoisonCannotFinishTheNpc()
	{
		NpcPoison poison = new NpcPoison();
		poison.onPoisonHit(6, T0);

		assertEquals(-1, poison.getHitsUntilDeath(200));
		assertEquals(-1, poison.getMillisUntilDeath(200, T0));
	}

	@Test
	public void healthEstimateFallsWithObservedPoisonDamage()
	{
		NpcPoison poison = new NpcPoison();
		poison.updateHealth(15, 30, 255);
		assertEquals(128, poison.getHealthEstimate());

		poison.onPoisonHit(6, T0);
		assertEquals(122, poison.getHealthEstimate());
	}

	@Test
	public void healthEstimateStaysUnknownWithoutAHealthBar()
	{
		NpcPoison poison = new NpcPoison();
		poison.updateHealth(-1, 30, 255);
		poison.onPoisonHit(6, T0);

		assertEquals(-1, poison.getHealthEstimate());
	}
}

package com.runelite.poisondynamite;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class NpcStatsManagerTest
{
	// Real response shape from the wiki bucket API (2026-08): one row per
	// infobox version, scalar stat fields, "id" as an array of strings.
	private static final String GUARD_RESPONSE = "{\"bucketQuery\":\"...\",\"bucket\":[" +
		"{\"id\":[\"11924\"],\"defence_level\":14,\"stab_defence_bonus\":5," +
		"\"slash_defence_bonus\":6,\"crush_defence_bonus\":7," +
		"\"magic_defence_bonus\":8,\"range_defence_bonus\":9}," +
		"{\"id\":[\"3254\",\"3255\"],\"defence_level\":21,\"stab_defence_bonus\":1," +
		"\"slash_defence_bonus\":2,\"crush_defence_bonus\":3," +
		"\"magic_defence_bonus\":4,\"range_defence_bonus\":5}]}";

	@Test
	public void parsesRowMatchingNpcId()
	{
		NpcStatsManager.NpcDefenceStats stats = NpcStatsManager.parseResponse(GUARD_RESPONSE, 3255);
		assertEquals(21, stats.defenceLevel);
		assertEquals(1, stats.stabDef);
		assertEquals(5, stats.rangeDef);
	}

	@Test
	public void fallsBackToFirstRowWhenIdNotFound()
	{
		NpcStatsManager.NpcDefenceStats stats = NpcStatsManager.parseResponse(GUARD_RESPONSE, 99999);
		assertEquals(14, stats.defenceLevel);
		assertEquals(9, stats.rangeDef);
	}

	@Test
	public void returnsNullOnEmptyBucket()
	{
		assertNull(NpcStatsManager.parseResponse("{\"bucket\":[]}", 1));
	}

	@Test
	public void returnsNullWhenBucketKeyMissing()
	{
		assertNull(NpcStatsManager.parseResponse("{\"error\":\"nope\"}", 1));
	}

	@Test
	public void missingAndNullFieldsDefaultToZero()
	{
		NpcStatsManager.NpcDefenceStats stats = NpcStatsManager.parseResponse(
			"{\"bucket\":[{\"id\":[\"5\"],\"defence_level\":null}]}", 5);
		assertEquals(0, stats.defenceLevel);
		assertEquals(0, stats.slashDef);
	}

	private static String parseApiJson(String wikitext)
	{
		return "{\"parse\":{\"title\":\"X\",\"wikitext\":{\"*\":" +
			new com.google.gson.Gson().toJson(wikitext) + "}}}";
	}

	@Test
	public void parsesUnversionedPoisonResistance()
	{
		String json = parseApiJson("{{Infobox Monster\n|id = 3010,3011\n|poisonous = No\n|poisonresistance = 100\n}}");
		assertEquals("100", NpcStatsManager.parsePoisonResistance(json, 3011));
	}

	@Test
	public void parsesVersionedPoisonResistanceMatchingId()
	{
		String json = parseApiJson("{{Infobox Monster\n|id1 = 100\n|poisonresistance1 = 0\n|id2 = 200,201\n|poisonresistance2 = poison\n}}");
		assertEquals("poison", NpcStatsManager.parsePoisonResistance(json, 201));
		assertEquals("0", NpcStatsManager.parsePoisonResistance(json, 100));
	}

	@Test
	public void fallsBackToFirstResistanceWhenIdUnmatched()
	{
		String json = parseApiJson("{{Infobox Monster\n|id1 = 100\n|poisonresistance1 = 200\n|id2 = 300\n|poisonresistance2 = 0\n}}");
		assertEquals("200", NpcStatsManager.parsePoisonResistance(json, 99999));
	}

	@Test
	public void returnsNullWhenResistanceMissing()
	{
		assertNull(NpcStatsManager.parsePoisonResistance(
			parseApiJson("{{Infobox Monster\n|id = 5\n|poisonous = No\n}}"), 5));
		assertNull(NpcStatsManager.parsePoisonResistance("{\"error\":{\"code\":\"missingtitle\"}}", 5));
	}

	@Test
	public void poisonImmunity()
	{
		NpcStatsManager.NpcDefenceStats base = new NpcStatsManager.NpcDefenceStats(1, 0, 0, 0, 0, 0);
		assertEquals(false, base.isPoisonImmune());
		assertEquals(false, base.withPoisonResistance("0").isPoisonImmune());
		assertEquals(true, base.withPoisonResistance("100").isPoisonImmune());
		assertEquals(true, base.withPoisonResistance("200").isPoisonImmune());
		assertEquals(true, base.withPoisonResistance("poison").isPoisonImmune());
	}

	@Test
	public void styleLookupPicksMatchingDefence()
	{
		NpcStatsManager.NpcDefenceStats stats = NpcStatsManager.parseResponse(GUARD_RESPONSE, 11924);
		assertEquals(5, stats.getDefenceForStyle("stab"));
		assertEquals(6, stats.getDefenceForStyle("slash"));
		assertEquals(7, stats.getDefenceForStyle("crush"));
		assertEquals(8, stats.getDefenceForStyle("magic"));
		assertEquals(9, stats.getDefenceForStyle("ranged"));
	}
}

package com.runelite.poisondynamite;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PoisonAttemptTest
{
	@Test
	public void reclickWhileAwaitingDetonationRestartsTheDetonationWindow()
	{
		PoisonAttempt attempt = new PoisonAttempt(null);
		attempt.ticksAwaitingDetonation = 5;

		// the previous throw was cancelled; this click is the live one
		assertTrue(attempt.absorbReclick());
		assertEquals(0, attempt.ticksAwaitingDetonation);
		assertTrue(attempt.awaitingDetonationHit);
	}

	@Test
	public void reclickDuringCountdownKeepsTheRunningTimer()
	{
		PoisonAttempt attempt = new PoisonAttempt(null);
		attempt.startCountdown();
		attempt.remainingTicks = 20;

		assertTrue(attempt.absorbReclick());
		assertEquals(20, attempt.remainingTicks);
	}

	@Test
	public void reclickOnAResolvedAttemptIsNotAbsorbed()
	{
		PoisonAttempt attempt = new PoisonAttempt(null);
		attempt.resolve(false);

		assertFalse(attempt.absorbReclick());
	}
}

